def merge_intervals(intervals):
    if not intervals:
        return []
    sirali = sorted(intervals, key=lambda x: x[0])
    birlesik = [list(sirali[0])]
    for baslangic, bitis in sirali[1:]:
        son = birlesik[-1]
        if baslangic <= son[1]:
            son[1] = max(son[1], bitis)
        else:
            birlesik.append([baslangic, bitis])
    return birlesik
