def topo_sort(graph):
    indegree = {}
    adj = {}

    for node in graph:
        if node not in indegree:
            indegree[node] = 0
        if node not in adj:
            adj[node] = []
        for nxt in graph[node]:
            if nxt not in indegree:
                indegree[nxt] = 0
            if nxt not in adj:
                adj[nxt] = []
            if nxt not in adj[node]:
                adj[node].append(nxt)
                indegree[nxt] += 1

    result = []
    available = sorted(n for n in indegree if indegree[n] == 0)

    while available:
        node = available.pop(0)
        result.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                available.append(nxt)
        available.sort()

    if len(result) != len(indegree):
        raise ValueError("Döngü tespit edildi")

    return result
